import{_ as a}from"./chunks/4cbd8caa7e5ad34ce1eb.0e8RglWB.js";import{_ as t,C as l,o as i,c as o,j as e,a as n,E as s,a6 as h}from"./chunks/framework.CnPv4DE1.js";const q=JSON.parse('{"title":"价值百万美元的技能栈（请按此顺序学习）","description":"","frontmatter":{"title":"价值百万美元的技能栈（请按此顺序学习）","originalTitle":"The $1 Million Dollar Skill Stack (Learn In This Order)","date":"2022-12-17","originalUrl":"https://thedankoe.com/letters/the-1-million-dollar-skill-stack-learn-in-this-order/","minutes":14,"sourceHash":"6cb6d800880caa7901adae3f68acf1c57d277f86fc52721772d59a89acf5e831","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-1-million-dollar-skill-stack-learn-in-this-order/"}]]},"headers":[],"relativePath":"letters/the-1-million-dollar-skill-stack-learn-in-this-order.md","filePath":"letters/the-1-million-dollar-skill-stack-learn-in-this-order.md"}'),m={name:"letters/the-1-million-dollar-skill-stack-learn-in-this-order.md"};function d(c,p,g,k,f,u){const r=l("ArticleMeta");return i(),o("div",null,[p[0]||(p[0]=e("h1",{id:"价值百万美元的技能栈-请按此顺序学习",tabindex:"-1"},[n("价值百万美元的技能栈（请按此顺序学习） "),e("a",{class:"header-anchor",href:"#价值百万美元的技能栈-请按此顺序学习","aria-label":'Permalink to "价值百万美元的技能栈（请按此顺序学习）"'},"​")],-1)),s(r),p[1]||(p[1]=h('<p><a href="https://www.youtube.com/embed/gpMwHtDwsCk?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>从我记事起，我就痴迷于学习。</p><p>是的，哪怕是多年前我每天玩 3-6 个小时电子游戏的时候。</p><p>我<em>总是</em>挤出时间来学习。虽然这常常会影响我学业或工作的质量——但我心里总清楚，获取知识迟早会有回报。</p><p>起初，我以为我对学习的渴望是“闪亮物体综合症”（Shiny Object Syndrome）。</p><p>你懂的……就是每个成功人士都会警告你要提防的那个“危险”玩意儿。</p><p>但是，如果我一阵阵的痴迷真的是闪亮物体综合症，我也不会有今天的成就。</p><p>我的道路通向了一个我十几岁时无法想象的境界。现在，我来这里与你分享这条路（不过是精简版的，没有那些坑坑洼洼）。</p><p>在过去的 10 年里，我曾痴迷于：</p><ul><li>健身</li><li>营养学</li><li>SEO (搜索引擎优化)</li><li>网页设计</li><li>网页开发</li><li>平面设计</li><li>数字艺术</li><li>社交媒体</li><li>内容写作</li><li>营销与销售</li><li>文案与漏斗</li><li>神经科学</li><li>哲学</li><li>灵性</li><li>自我提升</li><li>这个列表太长了，我就此打住……但还有更多。</li></ul><p>每次痴迷大约持续 1-3 个月。</p><p>当然，我不会只学一样东西。如果我在痴迷于文案写作时，有个营养学播客引起了我的兴趣，我依然会去听它。</p><p>十年后的结果如何？我实现了大多数人告诉你不可能会发生的事。即使他们没有明说这不可能，他们也会暗示这点。</p><p>这个不可能的成就是：</p><p><em>以我热爱的事情为生。</em></p><p>在不同的技能之间横跳，并没有妨碍我在起步阶段获得收入。不要陷入一种误区，认为在你的旅程初期无法替代你原来的收入（<a href="https://thedankoe.com/how-i-remember-everything-i-learn/" target="_blank" rel="noreferrer">如果你在现实世界中，在真实的人群面前，边学边构建的话。</a>）</p><p>首先，我们不要把闪亮物体综合症和技能叠加（skill stacking）混为一谈。</p><p>技能叠加 &gt; 成为专家 &gt; 因为害怕饱和、自动化或任何其他导致分心的借口而无所作为。</p><p>技能叠加能让你针对市场上<em>几乎</em>任何亟待解决的问题，构建出创造性的解决方案。</p><p>我能比专业的代运营机构获得更好的结果，仅仅是因为我对这个领域有更多的认知。</p><p>我知道 A 将如何影响 B，进而影响 C，并一直贯穿整个字母表（以及这个字母表从宏观宇宙的角度来看是如何合理的）。专家们往往只理解 A 如何影响 B，但到了 C……事情就开始变得模糊了，这就导致了有限的结果，哪怕这些结果对于接收方来说已经高于平均水平。</p><p>我们会在最后讨论为什么会这样，但首先，我们必须弄明白该学哪些技能（以及按照什么顺序）。</p><h2 id="叠加常青技能以实现盈利" tabindex="-1">叠加常青技能以实现盈利 <a class="header-anchor" href="#叠加常青技能以实现盈利" aria-label="Permalink to &quot;叠加常青技能以实现盈利&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>如果你关注了那些以追求成功为导向的社交媒体账号，你可能已经被他们吼着要去学某些技能了。</p><p>“开个代运营公司！”</p><p>“学习投 Facebook 广告！”</p><p>“做个个人品牌！”</p><p>这不是什么坏建议，但我想提出一种不同的方法。</p><p>所以，让我们把视角拉远，触及元层面（meta）。</p><p>为了盈利，你将进行价值与价值的交换（形式包括金钱、时间、社交杠杆、信息或专业知识）。</p><p>你将与其他人类进行这种价值交换。</p><p>在一切之上，人性与心理学占据着至高无上的地位。</p><p>因此，我们需要 3 样东西：</p><p><strong>1) 有价值的信息</strong> —— 一种与他人沟通的方式，它必须具有相关性、易于理解且可操作。</p><p><strong>2) 分发的媒介</strong> —— 一种将你有价值的信息呈现在人们面前的途径（否则没人看得到你的价值）。</p><p><strong>3) 以结果为导向的技能</strong> —— 一种为你用第 1 点和第 2 点吸引来的人群提供转变的方法。</p><p>信息、媒介，以及适用性。</p><p>这些技能相互作用、相辅相成。缺了其中任何一个，你都不会有结果。这就是为什么你需要 6 个多月的时间才能感觉自己弄懂了正在做什么。你不能只学了一项技能，就指望人们会主动找上门来（然后花钱买单）。</p><h3 id="信息" tabindex="-1">信息 <a class="header-anchor" href="#信息" aria-label="Permalink to &quot;信息&quot;">​</a></h3><p>人们，尤其是创作者，往往会忽略一个事实：人们会对任何事情产生兴趣。</p><p>自我认知和反思在这里是关键。</p><p>如果你对某个古怪的话题感兴趣，你是怎么产生兴趣的？你天生就对它感兴趣吗？当然不是。那么，你该如何让别人也产生兴趣，并吸引足够大的受众从而赖以为生呢？</p><p>如果你的话不能引起他人的共鸣，那不是他们的问题，而是你的问题。</p><p>你要么是：</p><ul><li>在用高阶水平讲话（而市场上 95% 的人都是新手）。</li><li>不懂得说服。你必须回答或暗示一个问题的答案：“这对我有什么好处？”</li><li>没有抓住他们的注意力，也没有将有价值的信息传递给那份注意力。</li></ul><p>关于最后一点，“价值”并不总是意味着具有可操作性。</p><p>价值可以通过内容创作的核心支柱来描述。</p><p>教育、娱乐和启发。</p><p>娱乐（对某些人来说）与教育一样有价值。</p><p>而且，“娱乐性”并不意味着非得幽默搞笑。一个能抓住眼球的相关统计数据或冷知识也可以是娱乐。学到新东西本身就是一种娱乐形式。</p><p>如果你想打造一条有价值的信息，你需要学习 2 项技能：</p><p><strong>1) 营销</strong> —— 为特定的人群创造一条引人注意、息息相关且有价值的信息。</p><p><strong>2) 销售</strong> —— 一个让人们意识到他们的问题，并为这些问题提供解决方案的过程。请注意，你不能只盯着那些自动就知道你在做的一切的人。这是一个过程。</p><p>销售也可以是讲故事的同义词。</p><p>它们都意味着通过以独特的方式克服问题来实现蜕变。</p><p>为了简洁起见，这封信不会深入探讨每一项技能，一封信是不可能做到这一点的。</p><p>但是，在最后一节中，我将告诉你如何最好地学习这些技能。</p><p>如果你想要我用来创建和推出高利润产品的营销与销售系统，<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">去看看 Digital Economics (数字经济学)</a>。</p><h3 id="媒介" tabindex="-1">媒介 <a class="header-anchor" href="#媒介" aria-label="Permalink to &quot;媒介&quot;">​</a></h3><p>在生活中，自律 = 自由（向 Jocko 致敬）。</p><p>在商业中，分发 = 自由。</p><p>对于互联网企业来说，分发来自于媒体和代码的结合。</p><p>编程是一项极好的高价值技能，尤其是当它与营销诀窍结合起来时。</p><p>构建软件，在网上进行分发，并真正通过营销获得用户，这是一个超人般的技能栈。大多数程序员只懂技术层面，却不懂人性层面。</p><p>然而，你们这里的许多人走的是创作者路线。</p><p>这种情况下，请记住，你需要掌握你所选软件的技术窍门。</p><p>你必须学习无代码工具（如建站工具、课程平台、笔记应用和效率组织工具），以最大化你技能栈的效果。</p><p>前面提到的你的信息，是带来互动、影响力和销售额的关键。</p><p>但如果你没有分发的媒介，很显然，人们就看不到那条信息。</p><p><em>这就是我过去犯错的地方。我过于执着去完善我的产品或服务了。</em></p><p>结果呢？</p><p>当然是没有销量。我并没有制定把<em>流量</em>吸引到我的自由职业服务的计划，结果搞了一个过于花哨的网站、Logo，浪费了 3 个月的“心血”打水漂。</p><p>而且，我没有任何数据。我是在没有先（通过内容和受众）进行测试的情况下，盲目地创造产品。</p><p>现在，在这封信中，我们采取的是一种元方法。</p><p>你通过发展漏斗顶部的社交媒体渠道来建立分发。</p><p>我们在 <a href="https://thedankoe.com/the-one-person-business-roadmap-99-of-creators-make-this-mistake/" target="_blank" rel="noreferrer">The One Person Business Roadmap (一人企业路线图)</a> 中讨论了分发和杠杆。</p><p>可以是任何渠道，但我建议新手从一个允许你掌控增长的社交平台开始。</p><p>YouTube、播客和博客都很好……但它们需要时间来积累。我会把它们留到你旅程的后期。把它们当作建立权威的平台，让它们随着时间去成长。</p><p>一开始，我强烈推荐 Twitter、Instagram 或 LinkedIn……Twitter 是我的最爱。<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">你唯一需要的技能就是写作</a>，并在此过程中学习其他技能。</p><p>这些“增长型”社交平台的原则都是一样的。你需要：</p><ul><li>一条有价值的信息</li><li>吸引眼球来看这条信息</li><li>不断努力让你的内容被分享</li><li>一个看起来就该有 100 万粉丝的品牌形象</li></ul><p>实现快速增长的花哨策略固然好。但是，最好还是专注于创作能在任何平台上带来粉丝的内容。</p><p>因此，用于分发信息的<em>媒介</em>，优先级要<em>高于</em>社交媒体平台本身。</p><p>写作和演讲。</p><p>这些才是分发你信息的媒介。</p><p>当它们与营销和销售相结合时，你就得到了文案写作和有说服力的演讲。</p><p>这是我所有社交媒体增长的基础。写好的 Newsletter 是 YouTube 的脚本。写好的推文是短视频（Reels）的脚本（并且可以复制粘贴到所有其他平台）。</p><p><a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">在《2小时作者》（2 Hour Writer）中</a>，我展示了我是如何撰写长篇 Newsletter、将其拆解为吸引人的推文，并将这些文字分发到所有平台的。</p><p>我所有的社交媒体增长都建立在我的写作之上。</p><p>演讲排第二（这是建立在书面脚本的基础上的）。</p><p>其他有助于阐明该信息的技能排第三。</p><p>所以，开始写作去清晰地表达你的信息吧。在社交媒体上建立分发网络。然后准备好了再去练习演讲。</p><h3 id="以结果为导向的技能" tabindex="-1">以结果为导向的技能 <a class="header-anchor" href="#以结果为导向的技能" aria-label="Permalink to &quot;以结果为导向的技能&quot;">​</a></h3><p>到目前为止，我们明白了你需要一条吸引人、有价值且有说服力的信息，外加一个分发媒介。</p><p>这就是你所需要的全部，但你可以通过在特定方面加以应用来强化这些技能。</p><ul><li>邮件营销</li><li>销售促单</li><li>平面设计</li><li>视频制作</li><li>动画制作</li><li>网页设计</li></ul><p>简而言之，你学习如何利用技术将媒介和信息<em>应用</em>于你自己或他人的业务中。</p><p>每一门生意都需要特定的技术才能在互联网上拉揽客户。</p><p>当你理解了这些部分是如何运作时，你就能通过这项技术交付特定的结果。</p><p>你能写出拉揽更多客户的邮件。</p><p>你能设计出吸引更多粉丝的图片。</p><p>你能制作出留住更多注意力的视频。</p><p>当你将营销、销售和沟通与某种特定技术相结合，并以此作为杠杆来获取每个人都想要的东西时，你就解锁了一个新层次的力量：</p><p>金钱、粉丝、声誉、机会、自由，以及整体的地位。</p><h2 id="叠加个人兴趣以彰显个性" tabindex="-1">叠加个人兴趣以彰显个性 <a class="header-anchor" href="#叠加个人兴趣以彰显个性" aria-label="Permalink to &quot;叠加个人兴趣以彰显个性&quot;">​</a></h2><p>在这些信件中，我谈到了如何将你自己变成细分领域并打造个人品牌。</p><p>但是，这同样适用于当你试图向不同客户画像、个人或企业进行销售的时候。</p><p>对于个人品牌而言，你的兴趣正是让你独一无二的东西。</p><p>当你有产品或服务要卖时，你的兴趣能帮你向下锚定一个细分领域，找到你要卖给谁。</p><p>如果我对健身感兴趣，我就会吸引对健身感兴趣的人。这意味着，我可以向他们介绍我的其他兴趣。</p><p>既然我了解健身圈，我对我的目标客户就了如指掌。我可以为健身教练拼凑出一套产品方案，帮助他们获得更好的结果。而且，这听起来就是比为了钱去和你鄙视的企业合作要愉快得多。</p><p>而且，如果我已经通过谈论健身（而不仅仅是商业）吸引了健身人群，那么我的目标受众<strong>就是</strong>我的受众。</p><p>我的兴趣是健身，所以我把相关内容融合进来，让自己更加独特。</p><p>我的目标客户是健身教练，他们是被我的健身内容吸引来的。既然他们在我的受众群体中，我就可以向他们输出教育内容，并向他们销售我与商业相关的产品方案。</p><p>明白这是怎么运作的了吗？</p><p>许多人害怕将自己的兴趣融入到一个专注的品牌中。</p><p><strong>“如果互动率不好怎么办？”</strong></p><p>那就是它还不够有趣。你没有击中相关的痛点，也没有说服他们为什么要关心。任何人都可以对任何事情产生兴趣。</p><p>拓宽话题，以初学者能懂的程度去表达。</p><p>（是的，这依然会吸引进阶水平的人。我在健身方面属于高阶，但仍然需要重温基础知识，所以我也会消费基础的健身内容。）</p><p><strong>“如果我的销量变少了怎么办？”</strong></p><p>你每篇帖子都在硬广推销吗？并没有。</p><p>放在5年的时间维度上看，如果你有20%的帖子是关于某个特定兴趣的，你真的认为那会影响整体收入吗？</p><p><strong>提示</strong>：不会的，如果有影响的话，它反而会促成更多的销量，因为你没有像其他人那样过度聚焦于一件事上。</p><p><strong>“如果我的兴趣和让我赚钱的事情毫无关系怎么办？”</strong></p><p>发挥创意。把它当作一种帮助人们理解的方式。</p><p>就像我把创作者比作DJ一样。</p><p>我喜欢电子舞曲（EDM），但那和商业没关系。所以我就找出其中的共通模式，用它让商业变得更有趣。</p><h2 id="叠加经验-把握细节与指引方向" tabindex="-1">叠加经验：把握细节与指引方向 <a class="header-anchor" href="#叠加经验-把握细节与指引方向" aria-label="Permalink to &quot;叠加经验：把握细节与指引方向&quot;">​</a></h2><p>起初毫无起色，随后一切爆发。</p><p>当你走在精通之路上，不是精通某项技能，而是精通某个领域……乃至你的生活，你将多次体验到这一课。</p><p>乔治·伦纳德（George Leonard）在《精通》（<em>Mastery</em>）一书中写道，精通是“一个神秘的过程，在这个过程中，起初困难的事情通过练习变得越来越容易，也越来越令人愉悦。”</p><p>这与即时满足恰恰相反——这也是为什么如果不去行动，就很难将其内化的原因。</p><p>我不打算在这里把你当成巨婴，给你提供获得即时回报的具体步骤。</p><p>但是，我会给你提供走上这条路所必需的元技能。</p><p>你的任务是：</p><p>在这条路上，将这些牢记于心。</p><p>当事情变得困难时，提醒自己这是过程的一部分。</p><p>通过坚持到底，你将经历短暂而猛烈的进步爆发期。拥抱它们。享受它们。</p><h3 id="爆发式构建" tabindex="-1">爆发式构建 <a class="header-anchor" href="#爆发式构建" aria-label="Permalink to &quot;爆发式构建&quot;">​</a></h3><p>帮助你学习上述技能的2项技能是<em>快速学习</em>和<em>快速执行</em>。</p><p>结合起来，我们可以把这些技能看作是一项技能：</p><p>构建（Building）。</p><p>我曾写过一整封信来探讨这个，<a href="https://thedankoe.com/how-i-remember-everything-i-learn/" target="_blank" rel="noreferrer">你应该读一读</a>……或者看一看视频。</p><p>简而言之，你需要这样做：</p><ul><li><strong>选择一个要模仿的项目。</strong> 这应该包含你正在努力学习的技能。</li><li><strong>开始构建你自己的版本。</strong> 为你的项目创建一个大纲，然后开始构建，直到你碰壁。</li><li><strong>寻求特定的知识。</strong> 当你碰壁时，去学习应对那个具体现实情况所需的技能。这能帮你滤除那些通过经验就能学到的废话。</li><li><strong>加分项：边学边教。</strong> 教学会找出你的知识盲区，这意味着你可以去寻求更具体的知识。</li></ul><p>我最喜欢的整合这封信中我们学到的一切的方法，就是构建一个一人企业。</p><p>为什么？</p><p>对我来说这显而易见，但对那些还没起步的人来说并非如此。</p><p>你可以<strong>在你自己的业务中</strong>练习上面提到的所有技能。</p><p>写作、演讲、营销、销售，以及设计、视频或电子邮件等互补技能。</p><p>你撰写内容、销售页面和促销文案。</p><p>你推销你自己的<a href="https://thedankoe.com/the-one-person-business-model-how-to-monetize-yourself/" target="_blank" rel="noreferrer">最小可行产品方案</a>（或者联盟推广产品，你甚至不需要有自己的产品），并获取数据来加以改进。</p><p>你设计你的头像、横幅、产品素材等等。</p><p>你的一人企业能否成功，取决于你在构建过程中边做边学的能力。</p><p>然后，凭借这些技能栈，你可以为几乎任何线上业务打造一份无法抗拒的产品方案……或者干脆把你一路上构建的东西变现。</p><h3 id="调整你的视角" tabindex="-1">调整你的视角 <a class="header-anchor" href="#调整你的视角" aria-label="Permalink to &quot;调整你的视角&quot;">​</a></h3><p><em>50年的1%是6个月。</em></p><p>而6个月只不过是开局的起点。</p><p>如果你走上了精通之路，你就是走上了一条终生之路。</p><p>当你敞开心扉，超越表面层次的生活时，你就能最终看到精通之路所展现出的人生深度、乐趣与反思。</p><p>我之前提过，闪亮物体综合征（Shiny object syndrome）并不是一件坏事。</p><p>“坏的”闪亮物体是那些让你偏离轨道的诱惑。</p><p>学习一项能与你现有技能互补的新技能并不坏。</p><p>你的技能会产生复利，并且没有人能把它们从你身上夺走。</p><p>当一个干扰项进入你的意识，而你<em>允许</em>自己的注意力收窄于此时，你就关闭了探索技艺深度的大门。</p><p>干扰项不过如此，只是路上一个暂时的颠簸。</p><p>因为一旦你开始了，你总是会回到这条路上，因为这是在这一生中实现你所求的唯一途径。</p><p>在这里需要注意的最重要的模式是：</p><p>起初毫无起色，随后一切爆发。</p><p>精通是一个循环过程，先是缓慢甚至停滞不前的进展，紧接着是指数级的飞跃。</p><p>在商业中，第一次指数级的飞跃通常发生在坚持努力6个月之后。紧随其后的是巨大的阻力。你会感觉自己原地踏步，一无所获。</p><p>把视角拉远。</p><p>注意到，那几个月潜在的绝望期也是旅程的一部分。</p><p>没人说你不该感觉良好（或糟糕）。</p><p>没人说这会很容易（或很难）。</p><p>没人说你应该富有（或贫穷）。</p><p>这些都是你大脑中固有的期望。</p><p>看透它们。</p><h3 id="逐渐觉察这个领域" tabindex="-1">逐渐觉察这个领域 <a class="header-anchor" href="#逐渐觉察这个领域" aria-label="Permalink to &quot;逐渐觉察这个领域&quot;">​</a></h3><p>我们讨论的一切都只是一份指南，直到通过直接经验将其巩固。</p><p>“起初毫无起色，随后一切爆发”只是一句听起来很爽的格言，直到你真正去体验它。</p><p>当你学习一项技能时，围绕着它会打开一个觉察场。</p><p>就像暗室里的一支蜡烛。</p><p>这让你能看到前进的下一步，并引导你走向下一项技能，进一步拓宽你的觉察范围。</p><p>一支蜡烛变成了两支。</p><p>然后是三支、四支，依此类推。</p><p>很快，你就能在这个曾经漆黑一片的房间里的大部分区域自由穿行。</p><p><em>起初毫无起色（拼图碎片杂乱无章、丑陋不堪），随后一切爆发（某块碎片咔哒一声严丝合缝，拼出一幅你能看懂的图像）。</em></p><p>这个“觉察场”就是你能够帮助他人、构建创造性解决方案并规划你的旅程的地方。</p><p>投入这条道路。</p><p>叠加常青技能（媒介、信息和结果）</p><p>叠加个人兴趣（为了彰显个性）</p><p>叠加经验（为了把握细节和指引方向）</p><p>给自己20年，而不是2个星期。</p><p><strong>—— 丹·柯（Dan Koe）</strong></p><p>当你准备好时，<a href="https://thedankoe.com/" target="_blank" rel="noreferrer">访问我的网站</a>，获取免费工具和产品，以此构建一个由你掌控的生活。</p><hr><p><a href="/en/letters/the-1-million-dollar-skill-stack-learn-in-this-order">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',200))])}const T=t(m,[["render",d]]);export{q as __pageData,T as default};
